message.content:
{
  "title": "The Mirror Rescue of Ruined Amberhall",
  "gate_token": "Bq7GnPJVqF81qNNgY7cyKg",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The cartographer examines the ruined city from a hill.",
      "visual_description": "Mara the Cartographer stands on a grassy hill overlooking the collapsed towers and broken spires of Amberhall, her brass compass glowing faintly in the dusk light.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The glass diver finds a way through a cracked window.",
      "visual_description": "Glass Diver presses his helmet against a shattered stained-glass window in the outer wall, the reflection of the city dancing on his coat.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "Inside a dim alley, Oracle Lamp flickers and speaks, its single eye eyeing a looming black tower with a twisted spire.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts the castle gate path.",
      "visual_description": "Tin Fox scurries along a cobblestone street, its blue glass eyes scanning the massive iron gates ahead, key-wind tail ticking.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Mara updates the map as the group gathers.",
      "visual_description": "Mara the Cartographer kneels over a spread map under a broken archway, inking a new route while the others arrive.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The sleeping tax collector blocks a magic door.",
      "visual_description": "A heavy oak door with glowing runes stands ajar; the Sleeping Tax Collector lies across the threshold, snoring on a ledger pillow.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "The glass diver swims through the magic door's reflection.",
      "visual_description": "Glass Diver steps into a puddle of moonlight, his body turning liquid as he passes through the reflected door on the ground.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Inside the tower, the oracle lamp reveals a hidden staircase.",
      "visual_description": "Oracle Lamp casts a beam of light on a spiral staircase hidden behind a tapestry of faded royal banners.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The tin fox detects a trap in the stairwell.",
      "visual_description": "Tin Fox stops, one paw raised, blue eyes glowing as it hears a faint click from the stone steps ahead.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Mara disarms the trap with her compass.",
      "visual_description": "Mara the Cartographer aligns her compass needle to a pressure plate, causing the floor to shift safely.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector wakes briefly and stamps a form.",
      "visual_description": "The Sleeping Tax Collector stirs, pulls a stamped paper from his sleeve, mumbles 'toll due,' then dozes off again.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "The group reaches the tower's top and finds a mirror vault.",
      "visual_description": "A circular room lined with mirrors reflects the group from all angles; in the center, a person is trapped inside a mirror cabinet.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The glass diver enters the mirror to free the prisoner.",
      "visual_description": "Glass Diver presses his helmet against the largest mirror, his reflection stepping through into the silvered space beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The oracle lamp warns of a collapsing floor.",
      "visual_description": "Oracle Lamp's flame flickers as cracks spread across the tower floor, dust raining from above.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver emerges with the rescued person.",
      "visual_description": "Glass Diver steps out of the mirror, holding the hand of a dazed figure; the mirror shatters behind them.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The group flees the tower as it crumbles.",
      "visual_description": "Mara, Tin Fox, and Oracle Lamp race down the staircase, the walls shaking and stones falling around them.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "They cross the old bridge to escape the city.",
      "visual_description": "A stone bridge spans a dry moat, old royal banners hanging tattered from its arch; the group runs across as the city gates collapse behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Mara closes her map as dawn breaks over the ruins.",
      "visual_description": "Mara the Cartographer rolls up her map on a hilltop, the ruined city glowing in the first light, her companions gathered around.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

